 90	        let active = self.request.as_ref().ok_or_else(|| invalid(0))?;
 91	        let mut released = 0;
 92	        for scene in &self.scenes[active.scene_count..] {
 93	            released = crate::memory::add(released, scene.storage_bytes()?)?;
 94	        }
 95	        // Prevalidate cleanup arithmetic before taking the checkpoint.
 96	        self.scenes[i]
 97	            .epoch
 98	            .checked_add(1)
 99	            .ok_or_else(crate::memory::arithmetic)?;
100	        let active = self.request.take().ok_or_else(|| invalid(0))?;
101	        let mut mark = active.mark;
102	        mark.epoch = self.scenes[i].epoch;
103	        self.rollback_internal(mark)?;
104	        self.scenes.truncate(active.scene_count);
105	        self.stats.live_bytes -= released;
106	        self.ignored = active.ignored;
107	        self.text_commands = active.text_commands;
