112	    pub fn abort_request(&mut self, draft: &DraftToken) -> Result<()> {
113	        self.draft_index(draft)?;
114	        let token = self.request.as_ref().ok_or_else(|| invalid(0))?.token;
115	        self.rollback_request(draft, token)
116	    }
