 19	impl SceneBuilder {
 20	    pub fn begin_draft(&mut self, scene: SceneId) -> Result<DraftToken> {
 21	        let i = self.index(scene)?;
 22	        if self.scenes[i].sealed || self.draft_depth >= 64 || self.request_protects_scene(scene) {
 23	            return Err(invalid(0));
 24	        }
 25	        if let Some(parent) = self.active_draft() {
 26	            if scene.index() < parent.scene_count {
 27	                return Err(invalid(0));
 28	            }
 29	        }
 30	        let nonce = self.serial()?;
 31	        let mark = self.checkpoint_unrestricted(scene)?;
 32	        let scene_count = self.scenes.len();
 33	        self.drafts[self.draft_depth] = Some(ActiveDraft {
 34	            scene,
 35	            nonce,
 36	            scene_count,
 37	        });
 38	        self.draft_depth += 1;
 39	        Ok(DraftToken {
 40	            mark,
 41	            nonce,
 42	            scene_count,
 43	            ignored: self.ignored,
 44	            text_commands: self.text_commands,
 45	        })
 46	    }
 47	    pub(crate) fn active_draft(&self) -> Option<ActiveDraft> {
 48	        self.draft_depth.checked_sub(1).and_then(|i| self.drafts[i])
 49	    }
 50	    pub(crate) fn draft_index(&self, token: &DraftToken) -> Result<usize> {
 51	        let active = self.active_draft().ok_or_else(|| invalid(0))?;
 52	        if active.scene != token.mark.scene
 53	            || active.nonce != token.nonce
 54	            || active.scene_count != token.scene_count
 55	        {
 56	            return Err(invalid(0));
 57	        }
 58	        let i = self.index(active.scene)?;
 59	        if self.scenes[i].sealed {
 60	            return Err(invalid(0));
 61	        }
 62	        if self.scenes[i]
 63	            .lengths()
 64	            .iter()
 65	            .zip(token.mark.lengths)
 66	            .any(|(now, then)| *now < then)
 67	        {
 68	            return Err(invalid(0));
 69	        }
 70	        Ok(i)
 71	    }
 72	    pub(crate) fn draft_slot(
 73	        &self,
 74	        token: &DraftToken,
 75	        table: usize,
 76	        slot: usize,
 77	        len: usize,
 78	    ) -> Result<usize> {
 79	        let i = self.draft_index(token)?;
 80	        let first = self
 81	            .request
 82	            .as_ref()
 83	            .map_or(token.mark.lengths[table], |r| {
 84	                if r.mark.scene == token.mark.scene {
 85	                    r.mark.lengths[table].max(token.mark.lengths[table])
 86	                } else {
 87	                    token.mark.lengths[table]
 88	                }
 89	            });
 90	        if slot < first || slot >= len {
 91	            return Err(invalid(0));
 92	        }
 93	        Ok(i)
 94	    }
 95	    /// Validation failure/cancellation leaves the token active and rollbackable.
 96	    pub fn commit_draft(
 97	        &mut self,
 98	        token: &DraftToken,
 99	        control: &mut dyn WorkControl,
100	    ) -> Result<()> {
101	        self.draft_index(token)?;
102	        if self.request_protects_draft(token) {
103	            return Err(invalid(0));
104	        }
105	        control.checkpoint().map_err(stopped)?;
106	        crate::validate::scene(self, token.mark.scene, control)?;
107	        self.draft_depth -= 1;
108	        self.drafts[self.draft_depth] = None;
109	        Ok(())
110	    }
111	    /// Rollback includes all descendants created after this graph checkpoint.
112	    /// Cleanup is unconditional even when the caller's work control has stopped.
113	    pub fn rollback_draft(&mut self, mut token: DraftToken) -> Result<()> {
114	        if self.request_protects_draft(&token) {
115	            return Err(invalid(0));
116	        }
117	        let i = self.draft_index(&token)?;
118	        let mut released = 0;
119	        for scene in &self.scenes[token.scene_count..] {
120	            released = crate::memory::add(released, scene.storage_bytes()?)?;
121	        }
122	        token.mark.epoch = self.scenes[i].epoch;
123	        self.rollback_internal(token.mark)?;
124	        self.scenes.truncate(token.scene_count);
125	        self.stats.live_bytes -= released;
126	        self.ignored = token.ignored;
127	        self.text_commands = token.text_commands;
128	        self.draft_depth -= 1;
129	        self.drafts[self.draft_depth] = None;
130	        Ok(())
131	    }
132	}
