 22	struct Split<'a> {
 23	    owner: u64,
 24	    head: &'a [Slot],
 25	    middle: &'a [Slot],
 26	    tail: &'a [Slot],
 27	    a: usize,
 28	    b: usize,
 29	}
 30	impl Split<'_> {
 31	    fn slice<T: JobElement>(&self, h: JobBuffer<T>, pool: RasterPool) -> Result<&[T]> {
 32	        let (owner, slot, serial) = h.identity();
 33	        if owner != self.owner || slot == self.a || slot == self.b {
 34	            return Err(invalid(0));
 35	        }
 36	        let s = if slot < self.a {
 37	            self.head.get(slot)
 38	        } else if slot < self.b {
 39	            self.middle.get(slot - self.a - 1)
 40	        } else {
 41	            self.tail.get(slot - self.b - 1)
 42	        }
 43	        .ok_or_else(|| invalid(0))?;
 44	        if !s.active || s.serial != serial || s.pool != pool {
 45	            return Err(invalid(0));
 46	        }
 47	        Ok(T::get(&s.data).ok_or_else(|| invalid(0))?)
 48	    }
 49	}
