 51	    fn cells(&self, h: JobBuffer<GridCell>) -> Result<&[GridCell]> {
 52	        self.slice(h, RasterPool::Grid)
 53	    }
 54	    fn references(&self, h: JobBuffer<u32>) -> Result<&[u32]> {
 55	        self.slice(h, RasterPool::Grid)
 56	    }
