 58	/// Exclusive job borrow prevents cache mutation, release, finish or teardown.
 59	/// Writes are elements of preallocated scratch/boundary/group/output buffers.
 60	/// Partial writes on engine error/cancel/panic are retained honestly; the owner
 61	/// may clear/reuse/discard them after the scope. No successful output is implied.
 62	pub struct RasterComposition<'a> {
 63	    job: &'a mut RasterJob,
 64	    cache: JobDashCache,
 65	}
 66	impl RasterJob {
 67	    /// Cache release while the scope remains live is rejected by Rust ownership.
 68	    /// ```compile_fail,E0499
 69	    /// use vexel_scene::*;
 70	    /// struct Run;
 71	    /// impl WorkControl for Run {
 72	    ///     fn charge(&mut self, _: WorkKind, _: u64) -> std::result::Result<(), Stop> { Ok(()) }
 73	    ///     fn checkpoint(&mut self) -> std::result::Result<(), Stop> { Ok(()) }
 74	    /// }
 75	    /// let source = std::sync::Arc::new(Vec::new());
 76	    /// let mut job = RasterJob::new(ChargeLedger::new(&source, 1 << 20, 128).unwrap()).unwrap();
 77	    /// let scratch = JobRasterScratch::new(&mut job, &mut Run).unwrap();
 78	    /// let scope = job.compose(&source, scratch.dash, &mut Run).unwrap();
 79	    /// job.release_all().unwrap();
 80	    /// scope.stats();
 81	    /// ```
 82	    pub fn compose<'a>(
 83	        &'a mut self,
 84	        source: &SourceOwner,
 85	        cache: JobDashCache,
 86	        control: &mut dyn WorkControl,
 87	    ) -> Result<RasterComposition<'a>> {
 88	        self.validate_source(source)?;
 89	        if cache.build_steps > 1_000_000 {
 90	            return Err(crate::types::limit(LimitKind::DashCache));
 91	        }
 92	        let (source, owner, work, slots) = self.composition_parts();
 93	        let reader = Split {
 94	            owner,
 95	            head: slots,
 96	            middle: &[],
 97	            tail: &[],
 98	            a: usize::MAX,
 99	            b: usize::MAX,
100	        };
101	        let view = cache_view(&reader, source, cache)?;
102	        let mut meter = JobWorkMeter {
103	            work,
104	            inner: control,
105	        };
106	        meter.checkpoint().map_err(stopped)?;
107	        view.validate(&mut meter)?; // exactly once, on the same job ledger
108	        Ok(RasterComposition { job: self, cache })
109	    }
110	}
111	impl RasterComposition<'_> {
112	    pub fn stats(&self) -> RenderMemoryStats {
113	        self.job.stats()
114	    }
115	    pub fn work(&self) -> RenderWorkStats {
116	        self.job.work()
117	    }
118	    pub fn charge_work(
119	        &mut self,
120	        kind: WorkKind,
121	        units: u64,
122	        control: &mut dyn WorkControl,
123	    ) -> Result<()> {
124	        let (_, _, work, _) = self.job.composition_parts();
125	        JobWorkMeter {
126	            work,
127	            inner: control,
128	        }
129	        .charge(kind, units)
130	        .map_err(stopped)
131	    }
132	    /// Supply two distinct mutable element slices plus the validated cache. All
133	    /// pools/identities/aliases are checked before borrowing or calling the engine.
134	    /// HRTB callback cannot return a cache/write borrow or unchecked lease/Vec.
135	    /// Borrowed writes cannot escape the callback.
136	    /// ```compile_fail
137	    /// use vexel_scene::*;
138	    /// fn escape<'a>(scope: &mut RasterComposition<'a>, a: JobBuffer<u8>,
139	    ///     b: JobBuffer<u32>, c: &mut dyn WorkControl) -> &'a mut [u8] {
140	    ///     scope.with_buffers(a, b, c, |_, values, _, _| Ok(values)).unwrap()
141	    /// }
142	    /// ```
143	    pub fn with_buffers<A: JobElement, B: JobElement, R>(
144	        &mut self,
145	        a: JobBuffer<A>,
146	        b: JobBuffer<B>,
147	        control: &mut dyn WorkControl,
148	        engine: impl FnOnce(
149	            ValidatedDashView<'_>,
150	            &mut [A],
151	            &mut [B],
152	            &mut dyn WorkControl,
153	        ) -> Result<R>,
154	    ) -> Result<R> {
155	        self.job.slice(a)?;
156	        self.job.slice(b)?;
157	        let (_, ai, _) = a.identity();
158	        let (_, bi, _) = b.identity();
159	        if ai == bi {
160	            return Err(invalid(0));
161	        }
162	        for slot in [ai, bi] {
163	            if matches!(
164	                self.job.slots[slot].pool,
165	                RasterPool::Dash | RasterPool::Grid
166	            ) {
167	                return Err(invalid(0));
168	            }
169	        }
170	        control.checkpoint().map_err(stopped)?;
171	        let (source, owner, work, slots) = self.job.composition_parts();
172	        let (low, high) = (ai.min(bi), ai.max(bi));
173	        let (head, rest) = slots.split_at_mut(low);
174	        let (left, rest) = rest.split_first_mut().ok_or_else(|| invalid(0))?;
175	        let (middle, rest) = rest.split_at_mut(high - low - 1);
176	        let (right, tail) = rest.split_first_mut().ok_or_else(|| invalid(0))?;
177	        let reader = Split {
178	            owner,
179	            head,
180	            middle,
181	            tail,
182	            a: low,
183	            b: high,
184	        };
185	        let view = cache_view(&reader, source, self.cache)?;
186	        let mut meter = JobWorkMeter {
187	            work,
188	            inner: control,
189	        };
190	        let (a_slot, b_slot) = if ai < bi {
191	            (left, right)
192	        } else {
193	            (right, left)
194	        };
195	        engine(
196	            ValidatedDashView { inner: view },
197	            A::get_mut(&mut a_slot.data).ok_or_else(|| invalid(0))?,
198	            B::get_mut(&mut b_slot.data).ok_or_else(|| invalid(0))?,
199	            &mut meter,
200	        )
201	    }
202	}
