  8	pub(crate) fn canonical(
  9	    subpaths: &[PathSubpath],
 10	    edges: TableRange,
 11	    geometry: &[Edge],
 12	    source_range: Span,
 13	    segments: impl Iterator<Item = PathSegment>,
 14	    control: &mut dyn WorkControl,
 15	) -> Result<()> {
 16	    let mut segments = segments.peekable();
 17	    let (mut first, mut end, mut open, mut record) = (edges.first, edges.first, false, 0);
 18	    let mut first_command = true;
 19	    let mut source_end = source_range.start;
 20	    let bound = edges.end().ok_or_else(crate::memory::arithmetic)?;
 21	    while let Some(segment) = segments.next() {
 22	        control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
 23	        if (first_command && !segment.command.eq_ignore_ascii_case(&b'M'))
 24	            || segment.source.start < source_end
 25	        {
 26	            return Err(invalid(0));
 27	        }
 28	        first_command = false;
 29	        source_end = segment.source.end;
 30	        let next = segment
 31	            .first_edge
 32	            .checked_add(segment.edge_count)
 33	            .ok_or_else(crate::memory::arithmetic)?;
 34	        if segment.first_edge < edges.first
 35	            || next > bound
 36	            || segment.source.start < source_range.start
 37	            || segment.source.end > source_range.end
 38	        {
 39	            return Err(invalid(0));
 40	        }
 41	        match segment.command.to_ascii_uppercase() {
 42	            b'M' => {
 43	                if segment.command_offset.is_none() {
 44	                    return Err(invalid(0));
 45	                }
 46	                if segment.first_edge != end || segment.edge_count != 0 {
 47	                    return Err(invalid(0));
 48	                }
 49	                // M's implicit closure is outside its zero-edge segment metadata.
 50	                let closed_end = segments.peek().map_or(bound, |s| s.first_edge);
 51	                if closed_end < end || closed_end - end > usize::from(open) {
 52	                    return Err(invalid(0));
 53	                }
 54	                if open {
 55	                    expect(subpaths, &mut record, first, closed_end, false)?;
 56	                } else if closed_end != end {
 57	                    return Err(invalid(0));
 58	                }
 59	                first = closed_end;
 60	                end = closed_end;
 61	                open = true;
 62	            }
 63	            b'Z' => {
 64	                if segment.command_offset.is_none() {
 65	                    return Err(invalid(0));
 66	                }
 67	                if segment.first_edge != end || segment.edge_count > usize::from(open) {
 68	                    return Err(invalid(0));
 69	                }
 70	                end = next;
 71	                if open {
 72	                    if first < end
 73	                        && geometry.get(end - 1).map(|e| e.b) != geometry.get(first).map(|e| e.a)
 74	                    {
 75	                        return Err(invalid(0));
 76	                    }
 77	                    expect(subpaths, &mut record, first, end, true)?;
 78	                }
 79	                open = false;
 80	            }
 81	            _ => {
 82	                if segment.first_edge != end {
 83	                    return Err(invalid(0));
 84	                }
 85	                end = next;
 86	                open = true;
 87	            }
 88	        }
 89	    }
 90	    if open {
 91	        if bound < end || bound - end > 1 {
 92	            return Err(invalid(0));
 93	        }
 94	        expect(subpaths, &mut record, first, bound, false)?;
 95	        end = bound;
 96	    }
 97	    if end != bound || record != subpaths.len() {
 98	        return Err(invalid(0));
 99	    }
100	    Ok(())
101	}
102	fn expect(
103	    paths: &[PathSubpath],
104	    record: &mut usize,
105	    first: usize,
106	    end: usize,
107	    closed: bool,
108	) -> Result<()> {
109	    let count = end
110	        .checked_sub(first)
111	        .ok_or_else(crate::memory::arithmetic)?;
112	    if count == 0 {
113	        return Ok(());
114	    }
115	    let value = paths.get(*record).ok_or_else(|| invalid(0))?;
116	    if value.first_edge != first || value.edge_count != count || value.closed != closed {
117	        return Err(invalid(0));
118	    }
119	    *record = record
120	        .checked_add(1)
121	        .ok_or_else(crate::memory::arithmetic)?;
122	    Ok(())
123	}
