125	/// Builder publication groups segments by monotonic shape insertion slot. The
126	/// immutable table is searched with controlled probes, not rescanned per shape.
127	pub(crate) fn scene_segments<'a>(
128	    segments: &'a [ScenePathSegment],
129	    shape: usize,
130	    control: &mut dyn WorkControl,
131	) -> Result<&'a [ScenePathSegment]> {
132	    fn bound(
133	        segments: &[ScenePathSegment],
134	        shape: usize,
135	        after: bool,
136	        control: &mut dyn WorkControl,
137	    ) -> Result<usize> {
138	        let (mut lo, mut hi) = (0, segments.len());
139	        while lo < hi {
140	            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
141	            let mid = lo + (hi - lo) / 2;
142	            let index = segments[mid].shape.index();
143	            if index < shape || (after && index == shape) {
144	                lo = mid + 1;
145	            } else {
146	                hi = mid;
147	            }
148	        }
149	        Ok(lo)
150	    }
151	    let first = bound(segments, shape, false, control)?;
152	    let end = bound(segments, shape, true, control)?;
153	    segments.get(first..end).ok_or_else(|| invalid(0))
154	}
