 18	fn lexical(path: &str) -> LexicalDocument {
 19	    LexicalDocument::parse(Arc::new(format!("<svg><g id=\"target\"><path d=\"{path}\"/></g><g/></svg>").into_bytes()), 1 << 20, &mut Run).unwrap()
 20	}
