 24	fn parsed(doc: &LexicalDocument, transform: Affine) -> ShapeInput {
 25	    let source = doc.source();
 26	    let start = source.windows(4).position(|b| b == b" d=\"").unwrap() + 4;
 27	    let end = start + source[start..].iter().position(|b| *b == b'"').unwrap();
 28	    let element_start = source.windows(5).position(|b| b == b"<path").unwrap();
 29	    let element_end = end + 3;
 30	    let path = vexel_svg_path::parse_path(source, Span { start, end }, transform, Default::default()).unwrap();
 31	    ShapeInput { edge_colors: vec![[4, 3, 2, 255]; path.edges.len()], path,
 32	        shape: Shape::new(SourceMap { element: Span { start: element_start, end: element_end }, transform, transform_node: None }) }
 33	}
 34	fn token(doc: &LexicalDocument, name: &[u8]) -> ElementId {
 35	    ElementId(doc.tokens().iter().position(|t| t.local_name.slice(doc.source()) == Some(name)).unwrap())
 36	}
 37	fn publish(b: &mut SceneBuilder, doc: &LexicalDocument) -> ShapeId {
 38	    b.append_shape(b.root_id(), parsed(doc, identity()), &mut Run).unwrap()
 39	}
