 42	// admitted through the shared builder and not through this cache's storage count.
 43	struct TextProvider { commands: usize, fail: bool }
 44	impl MediaProvider for TextProvider {
 45	    fn layout_text(&mut self, request: TextRequest<'_>, control: &mut dyn WorkControl) -> std::result::Result<TextLayout, MediaError> {
 46	        if self.fail { return Err(MediaError::Corrupt); }
 47	        request.validate(control).map_err(|_| MediaError::Invalid)?;
 48	        Ok(TextLayout { glyphs: vec![TextGlyph { glyph_id: Some(1), x: 0., y: 0., advance: 1., commands: TableRange { first: 0, count: self.commands } }],
 49	            commands: vec![TextCommand { verb: TextVerb::Move, values: [0.; 6] }; self.commands],
 50	            advance_width: 1., ascent: 1., descent: 0., leading: 0. })
 51	    }
 52	    fn decode_image(&mut self, encoded: &[u8], control: &mut dyn WorkControl) -> std::result::Result<ImagePixels, MediaError> {
 53	        control.checkpoint().map_err(|_| MediaError::Invalid)?;
 54	        if encoded != b"owned-fixture" { return Err(MediaError::Corrupt); }
 55	        Ok(image().pixels)
 56	    }
 57	}
 58	fn text_request() -> TextRequest<'static> {
 59	    TextRequest { text: b"x", font_families: &[], size_points: 12., weight: 400., style: TextStyle::Normal, letter_spacing_points: 0. }
 60	}
 61	fn media_use(b: &mut SceneBuilder, d: &DraftToken, doc: &LexicalDocument,
 62	    layout: &TextLayout, late_failure: bool, control: &mut dyn WorkControl) -> Result<ShapeId> {
 63	    let request = b.begin_request(d, control)?;
 64	    let result = (|| {
 65	        // Full provider layout validation is provider work, not cache admission.
 66	        layout.validate(control)?;
 67	        b.admit_text_commands(d, layout.commands.len(), 5, control)?;
 68	        let id = b.append_shape(b.root_id(), parsed(doc, identity()), control)?;
 69	        if late_failure { return Err(Diagnostic { kind: ErrorKind::OutOfMemory, offset: 5 }); }
 70	        b.commit_request(d, request, control)?;
 71	        Ok(id)
 72	    })();
 73	    if result.is_err() { b.rollback_request(d, request)?; }
 74	    result
 75	}
