 78	    let doc = lexical("M0 0 L1 1 Z");
 79	    let mut b = build(&doc);
 80	    let d = b.begin_draft(b.root_id()).unwrap();
 81	    let mut provider = TextProvider { commands: 262144, fail: false };
 82	    let layout = provider.layout_text(text_request(), &mut Run).unwrap();
 83	    let cache_commands = layout.commands.len();
 84	    for i in 1..=16 {
