160	fn grid_job(source: &SourceOwner) -> (RasterJob, JobRasterScratch, JobBuffer<u8>, JobBuffer<GridCell>, JobBuffer<u32>) {
161	    let mut j = RasterJob::new(ChargeLedger::new(source, 1 << 20, 128).unwrap()).unwrap();
162	    let scratch = JobRasterScratch::new(&mut j, &mut Run).unwrap();
163	    let cells = j.buffer(RasterPool::Grid, 65536, &mut Run).unwrap();
164	    let refs = j.buffer(RasterPool::Grid, 1000000, &mut Run).unwrap();
165	    j.extend(scratch.dash.segments, &[DashSegment { edge: Edge { a: Point { x: 0., y: 0. }, b: Point { x: 1., y: 1. } }, start_cap: Linecap::Butt, end_cap: Linecap::Butt }], &mut Run).unwrap();
166	    j.extend(cells, &[GridCell { first: 0, count: 1 }], &mut Run).unwrap();
167	    j.extend(refs, &[0], &mut Run).unwrap();
168	    j.extend(scratch.dash.shapes, &[JobDashRange { segments: TableRange { first: 0, count: 1 }, joins: TableRange::EMPTY,
169	        grid_cells: cells, grid_refs: refs, grid_min_x: 0., grid_min_y: 0., grid_cell_size: 1., grid_columns: 1, grid_rows: 1 }], &mut Run).unwrap();
170	    j.extend(scratch.active_edges, &[0; 32], &mut Run).unwrap();
171	    j.extend(scratch.pixel_runs, &[PixelRun { first_x: 0, end_x: 1, center_only: false }; 32], &mut Run).unwrap();
172	    let output = j.buffer(RasterPool::Output, 128, &mut Run).unwrap();
173	    j.extend(output, &[0; 128], &mut Run).unwrap();
174	    (j, scratch, output, cells, refs)
175	}
