569	impl DefinitionPlanner for MaskPlanner {
570	    fn plan_owned_definition<'src>(&mut self, ctx: &mut DefinitionContext<'src, '_>,
571	        kind: DefinitionKind, element: ElementId, owner: DefinitionOwner, transform: Affine,
572	        _: [f64; 4], style: &CssPaint<'src>, control: &mut dyn WorkControl) -> Result<ProductionDefinitionPlan<'src>> {
573	        owner.validate(ctx)?;
574	        assert_eq!(kind, DefinitionKind::Mask);
575	        self.target.validate(ctx, control)?;
576	        let bytes = std::mem::size_of::<Expansion<'src>>();
577	        let lease = ctx.ledger.admit(AllocationTag::ReferenceIndex, bytes)?;
578	        let mut expansions = Vec::new();
579	        if expansions.try_reserve_exact(1).is_err() {
580	            ctx.ledger.release(lease)?;
581	            return Err(Diagnostic { kind: ErrorKind::OutOfMemory, offset: 0 });
582	        }
583	        // Exact fixture reservation; reject any allocator excess, never hide it.
584	        if expansions.capacity() != 1 {
585	            drop(expansions); ctx.ledger.release(lease)?;
586	            return Err(Diagnostic { kind: ErrorKind::Limit(LimitKind::ReservedBytes), offset: 0 });
587	        }
588	        expansions.push(Expansion { range: TableRange { first: element.0, count: 1 }, transform, viewport: [100., 100.], style: *style,
589	            flavor: self.flavor, post: PostOperation::AttachTargetedMask(self.target) });
590	        self.lease = Some(lease);
591	        Ok(ProductionDefinitionPlan::Definition(DefinitionPlan {
592	            descriptor: DefinitionDescriptor::Mask(MaskDescriptor { luminance: false, region_object_bounding_box: false, custom_region: false,
593	                region: [0., 0., 1., 1.], region_transform: identity(), source_offset: 5 }), expansions, post: PostOperation::None }))
594	    }
595	}
