   187	                .charge(crate::WorkKind::Media, 1)
   188	                .map_err(crate::types::stopped)?;
   189	            glyph.commands.require(self.commands.len(), 0)?;
   190	            if ![glyph.x, glyph.y, glyph.advance]
   191	                .into_iter()
   192	                .all(f64::is_finite)
