288	fn original_post_close_smooth_and_explicit_geometry_metadata_freeze_and_frame() {
289	    let cases = [
290	        "M1 1 C2 2 3 3 4 4 Z S6 6 7 7",
291	        "M1 1 C2 2 3 3 4 4 Z C1 1 6 6 7 7",
292	        "M1 1 C2 2 3 3 4 4 Z Z S6 6 7 7 Z S8 8 9 9",
293	        "M1 1 L4 4 Z L7 7 M10 10 L11 11 Z L12 12",
294	        "M1 1 L4 4 Z L7 7 M10 10 L11 11",
295	    ];
296	    let mut pair = Vec::new();
297	    for data in cases {
298	        let doc = lexical(data);
299	        let mut b = build(&doc);
300	        let root = b.root_id();
301	        let d = b.begin_draft(root).unwrap();
302	        let transform = Affine { a: 2., d: 3., e: 9., f: -4., ..identity() };
303	        let input = parsed(&doc, transform);
304	        let edges = input.path.edges.clone();
305	        let subpaths = input.path.subpaths.clone();
306	        let segments = input.path.segments.clone();
307	        let numbers = input.path.numbers.clone();
308	        let first = b.append_shape(root, input, &mut Run).unwrap();
309	        let second = b.append_shape(root, parsed(&doc, transform), &mut Run).unwrap();
310	        b.commit_draft(&d, &mut Run).unwrap();
311	        b.seal(root, &mut Run).unwrap();
312	        let graph = b.freeze_controlled(&mut Run).unwrap();
313	        let view = graph.root();
314	        assert_eq!(view.shape(first).unwrap().edges.slice(view.edges).unwrap(), edges);
315	        for (i, original) in subpaths.iter().enumerate() {
316	            let published = view.path_subpaths[i + subpaths.len()];
317	            assert_eq!(published.first_edge, original.first_edge + edges.len());
318	            assert_eq!(published.edge_count, original.edge_count);
319	            assert_eq!(published.closed, original.closed);
320	        }
321	        for (i, original) in segments.iter().enumerate() {
322	            let published = view.path_segments[i + segments.len()];
323	            assert_eq!(published.shape, second);
324	            assert_eq!(published.path.source, original.source);
325	            assert_eq!(published.path.command_offset, original.command_offset);
326	            assert_eq!(published.path.first_edge, original.first_edge + edges.len());
327	            assert_eq!(published.path.first_number, original.first_number + numbers.len());
328	            assert_eq!(published.path.command, original.command);
329	            let mut expected = *original;
330	            expected.first_edge += edges.len();
331	            expected.first_number += numbers.len();
332	            assert_eq!(published.path, expected);
333	        }
334	        assert_eq!(&view.path_numbers[..numbers.len()], numbers);
335	        assert_eq!(&view.path_numbers[numbers.len()..], numbers);
336	        let mut frame = FrameBuilder::new(view, 1 << 20).unwrap();
337	        frame.replace_edges(edges.iter().chain(&edges).copied().collect(), &mut Run).unwrap();
338	        let frame = frame.finish(&mut Run).unwrap();
339	        assert_eq!(frame.view().path_subpaths, view.path_subpaths);
340	        assert_eq!(frame.view().path_segments, view.path_segments);
341	        if pair.len() < 2 { pair.push(edges); }
342	    }
343	    assert_eq!(pair[0], pair[1]); // exact original implicit/explicit smooth assertion
344	}
